import os
import re
import sys
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)

_zones = {}


def zone(name):
    z = _zones.get(name)
    if z is None:
        z = _zones[name] = ZoneInfo(name)
    return z


def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8", errors="replace")
    if text.startswith("\ufeff"):
        text = text[1:]
    return text


def lines_of(text):
    return [ln for ln in text.splitlines() if ln.strip() != ""]


def to_epoch(dt):
    """aware datetime -> integer epoch seconds"""
    d = dt - EPOCH
    return d.days * 86400 + d.seconds  # microseconds ignored (none expected)


def wall_to_epoch(naive, zname, dst_hint=None):
    """Local wall time -> epoch seconds. dst_hint: True/False/None for repeated times."""
    z = zone(zname)
    a = naive.replace(tzinfo=z, fold=0)
    b = naive.replace(tzinfo=z, fold=1)
    oa, ob = a.utcoffset(), b.utcoffset()
    if oa == ob or dst_hint is None:
        return to_epoch(a)
    # ambiguous: the DST occurrence has the larger UTC offset
    if dst_hint:
        return to_epoch(a if oa > ob else b)
    return to_epoch(a if oa < ob else b)


def standard_offset(naive, zname):
    z = zone(zname)
    dt = naive.replace(tzinfo=z, fold=0)
    return dt.utcoffset() - (dt.dst() or timedelta(0))


def parse_iso(s):
    s = s.strip()
    if s.endswith("Z") or s.endswith("z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=UTC)
    return dt


def norm_dir(s):
    s = s.strip().upper()
    if s in ("IN", "I", "K", "CLOCK_IN"):
        return "IN"
    if s in ("OUT", "O", "G", "CLOCK_OUT"):
        return "OUT"
    return None


# ---------------------------------------------------------------- parsers
# Each parser yields (punch_id, employee, direction, epoch_seconds)

def parse_abbr_csv(text, zname):
    header = None
    for row in csv.reader(lines_of(text)):
        row = [c.strip() for c in row]
        if not row:
            continue
        if "Badge" in row and "Punch" in row:
            header = {name: i for i, name in enumerate(row)}
            continue
        if header is None:
            continue
        try:
            badge = row[header["Badge"]]
            d = norm_dir(row[header["Punch"]])
            ds = row[header["Date"]]
            ts = row[header["Time"]]
            zab = row[header["Zone"]] if "Zone" in header else ""
            pid = row[header["Record"]]
