            h = h % 12
            if ap == "PM":
                h += 12
        zu = zab.upper()
        hint = None
        if zu.endswith("DT"):
            hint = True
        elif zu.endswith("ST"):
            hint = False
        naive = datetime(yr, mo, da, h, mi, se)
        yield pid, badge, d, wall_to_epoch(naive, zname, hint)


