            try:
                schema = int(o["schema"])
            except (TypeError, ValueError):
                pass
            continue
        if o.get("heartbeat") is True:
            continue
        try:
            if schema == 2:
                pid = o["punch_id"]
                emp = o["employee"]
                d = norm_dir(o["direction"])
                t = math.floor(Fraction(str(o["epoch_ms"])) / 1000) if not isinstance(o["epoch_ms"], float) \
