            else:
                pid = o["id"]
                emp = o["emp"]
                d = norm_dir(o["dir"])
                if "ts_ms" in o:
                    v = o["ts_ms"]
                    t = math.floor(v / 1000) if isinstance(v, float) else v // 1000
                else:
