def parse_legacy(text, zname):
    offset = None  # seconds; None -> site's standard time
    for ln in lines_of(text):
        t = ln[0]
        if t == "H":
            m = re.match(r"^([+-])(\d\d)(\d\d)", ln[13:18].strip()) if len(ln) > 13 else None
