        per_emp.setdefault(emp, []).append((ep, 0 if dr == "OUT" else 1, site, pid, dr))

    home_zone = {e: sites[h][0] for e, h in employees.items()}

    stats = {e: dict(shifts=0, paid=0, ot=0, night=0, pay=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    def rnd(ep, site):
        off = offset_at(ep, sites[site][0])
        # offset_at is bucketed by 900s; exact offset at ep:
        dt = datetime.fromtimestamp(ep, UTC).astimezone(zone(sites[site][0]))
        off = int(dt.utcoffset().total_seconds())
        rem = (ep + off) % 360
        return ep + (360 - rem if rem >= 180 else -rem)

    for emp, plist in per_emp.items():
        plist.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        hz = home_zone[emp]
        kept = []
        last = None
        for ep, _, site, pid, dr in plist:
            r = rnd(ep, site)
            if last is not None and last[4] == dr and ep - last[0] <= 300:
                if pstart <= local_date(r, hz) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            last = (ep, None, site, pid, dr)
            kept.append((r, dr, site))
        # pair
        shifts = []
        pending = None

        def wd(r):
            return local_date(r, hz)

        for r, dr, site in kept:
            if dr == "IN":
                if pending is not None:
                    if pstart <= wd(pending[0]) <= pend:
                        exc["open_shifts"] += 1
                pending = (r, site)
            else:
                if pending is None:
                    if pstart <= wd(r) <= pend:
                        exc["orphan_outs"] += 1
                elif r - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], r, pending[1]))
                    pending = None
                else:
                    if pstart <= wd(pending[0]) <= pend:
                        exc["open_shifts"] += 1
                    if pstart <= wd(r) <= pend:
                        exc["orphan_outs"] += 1
                    pending = None
        if pending is not None and pstart <= wd(pending[0]) <= pend:
            exc["open_shifts"] += 1

        # in-period shifts
        mine = []
        for rin, rout, site in shifts:
            w = wd(rin)
            if not (pstart <= w <= pend):
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(rin, rout, sites[site][0]) // 60, paid)
            mine.append((rin, w, paid, night))
        mine.sort(key=lambda x: x[0])
        day_cum = {}
        week_cum = {}
        st = stats[emp]
        for rin, w, paid, night in mine:
            c = day_cum.get(w, 0)
            dot = max(0, c + paid - 480) - max(0, c - 480)
            day_cum[w] = c + paid
            monday = w - timedelta(days=w.weekday())
            nd = paid - dot
            wc = week_cum.get(monday, 0)
            wot = max(0, wc + nd - 2400) - max(0, wc - 2400)
            week_cum[monday] = wc + nd
            ot = dot + wot
            reg = paid - ot
            rl = rates.get(emp, [])
            rate = Fraction(0)
            for eff, rv in rl:
                if eff <= w:
                    rate = rv
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            st["shifts"] += 1
            st["paid"] += paid
            st["ot"] += ot
            st["night"] += night
            st["pay"] += pay

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tot_cents = 0
    for e in employees:
        s = stats[e]
        cents = money(s["pay"])
        out_emps[e] = {
            "shifts": s["shifts"], "paid_minutes": s["paid"], "overtime_minutes": s["ot"],
            "night_minutes": s["night"], "gross": fmt_cents(cents),
        }
        tot["shifts"] += s["shifts"]
        tot["paid_minutes"] += s["paid"]
        tot["overtime_minutes"] += s["ot"]
        tot["night_minutes"] += s["night"]
        tot_cents += cents
    tot["gross"] = fmt_cents(tot_cents)

    result = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": {
            "open_shifts": exc["open_shifts"], "orphan_outs": exc["orphan_outs"],
            "duplicates_dropped": exc["duplicates_dropped"], "corrections_applied": applied,
        },
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outp))
    os.makedirs(d, exist_ok=True)
    with open(outp, "w") as f:
        json.dump(result, f, indent=1, sort_keys=True)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
