        h, mi, se = int(m.group(1)), int(m.group(2)), int(m.group(3))
        ap = m.group(4)
        if ap:
            ap = ap.upper()
            h = h % 12
            if ap == "PM":
                h += 12
        zu = zab.upper()
        hint = None
        if zu.endswith("DT"):
            hint = True
        elif zu.endswith("ST"):
            hint = False
        naive = datetime(yr, mo, da, h, mi, se)
        yield pid, badge, d, wall_to_epoch(naive, zname, hint)


def parse_epoch_jsonl(text, zname):
    schema = 1
    for ln in lines_of(text):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            try:
                schema = int(o["schema"])
            except (TypeError, ValueError):
                pass
            continue
        if o.get("heartbeat") is True:
            continue
        try:
            if schema == 2:
                pid = o["punch_id"]
                emp = o["employee"]
                d = norm_dir(o["direction"])
                t = math.floor(o["epoch_ms"] / 1000) if isinstance(o["epoch_ms"], float) \
                    else o["epoch_ms"] // 1000
            else:
                pid = o["id"]
                emp = o["emp"]
                d = norm_dir(o["dir"])
                if "ts_ms" in o:
                    v = o["ts_ms"]
                    t = math.floor(v / 1000) if isinstance(v, float) else v // 1000
                else:
                    t = math.floor(o["ts"])
        except (KeyError, TypeError, ValueError, AttributeError):
            continue
        if d is None:
            continue
        yield str(pid), str(emp).strip(), d, int(t)


def parse_offset_csv(text, zname):
    header = None
    for row in csv.reader(lines_of(text), delimiter=";"):
        row = [c.strip() for c in row]
