        if "punch_id" in row and "timestamp" in row:
            header = {name: i for i, name in enumerate(row)}
            continue
        if header is None:
            continue
        try:
            pid = row[header["punch_id"]]
            emp = row[header["employee"]]
            d = norm_dir(row[header["event"]])
            ts = row[header["timestamp"]]
        except (KeyError, IndexError):
            continue
        if d is None:
