        yield pid, emp, d, to_epoch(parse_iso(ts))


def parse_legacy(text, zname):
    offset = None  # seconds; None -> site's standard time
    for ln in lines_of(text):
        t = ln[0]
        if t == "H":
            m = re.match(r"^([+-])(\d\d)(\d\d)", ln[13:18].strip()) if len(ln) > 13 else None
            if m:
                offset = (1 if m.group(1) == "+" else -1) * (int(m.group(2)) * 3600 + int(m.group(3)) * 60)
            else:
                offset = None
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = norm_dir(ln[15:16])
            dts = ln[16:30]
            if d is None or len(dts) < 14:
                continue
            naive = datetime(int(dts[0:4]), int(dts[4:6]), int(dts[6:8]),
                             int(dts[8:10]), int(dts[10:12]), int(dts[12:14]))
            if offset is None:
                off = standard_offset(naive, zname)
                off_s = off.days * 86400 + off.seconds
            else:
                off_s = offset
            epoch = to_epoch(naive.replace(tzinfo=UTC)) - off_s
            emp = badge
            if badge.isdigit():
                emp = "E" + badge.zfill(4)
            elif not badge.upper().startswith("E"):
                emp = "E" + badge
            yield pid, emp, d, epoch


def parse_de_tsv(text, zname):
    header = None
    for ln in lines_of(text):
        row = [c.strip() for c in ln.split("\t")]
        if "Ausweis" in row and "Buchung" in row:
