        da, mo, yr = (int(x) for x in ds.split("."))
        parts = us.split(":")
        h, mi = int(parts[0]), int(parts[1])
        se = int(parts[2]) if len(parts) > 2 else 0
        zu = zz.upper()
        hint = True if zu == "MESZ" else (False if zu == "MEZ" else None)
