PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------- helpers
def list_files(d):
    out = []
    for root, dirs, files in os.walk(d):
        dirs.sort()
        for f in sorted(files):
            out.append(os.path.join(root, f))
    return out


def exact_offset(epoch, zname):
    dt = datetime.fromtimestamp(epoch, UTC).astimezone(zone(zname))
    return int(dt.utcoffset().total_seconds())


def local_date(epoch, zname):
    return (datetime.fromtimestamp(epoch, UTC).astimezone(zone(zname))).date()


_off_cache = {}


def offset_bucket(epoch, zname):
    key = (zname, epoch // 900)
    v = _off_cache.get(key)
    if v is None:
        v = _off_cache[key] = exact_offset((epoch // 900) * 900, zname)
    return v


def night_seconds(a, b, zname):
    """Seconds in [a,b) (epoch) falling in 22:00-06:00 local time."""
    total = 0
    t = a
    while t < b:
        off = offset_bucket(t, zname)
        nxt = min(b, (t // 900 + 1) * 900)
        while nxt < b and offset_bucket(nxt, zname) == off:
            nxt = min(b, nxt + 900)
        ls, le = t + off, nxt + off
        k = ls // 86400
        while k * 86400 < le:
            base = k * 86400
            for w0, w1 in ((base, base + 21600), (base + 79200, base + 86400)):
                lo, hi = max(ls, w0), min(le, w1)
                if hi > lo:
                    total += hi - lo
            k += 1
        t = nxt
    return total


def to_cents(fr):
    return math.floor(fr * 100 + Fraction(1, 2))


def fmt_cents(n):
    return "%d.%02d" % (n // 100, n % 100)


# ---------------------------------------------------------------- main
def main(inp, outp):
    with open(os.path.join(inp, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(inp, "sites.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            sites[r["site"].strip()] = (r["timezone"].strip(), r["format"].strip())

    employees = {}
    with open(os.path.join(inp, "employees.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    with open(os.path.join(inp, "rates.csv"), newline="", encoding="utf-8-sig") as f:
        for r in csv.DictReader(f):
            rates.setdefault(r["employee_id"].strip(), []).append(
                (date.fromisoformat(r["effective_from"].strip()), Fraction(Decimal(r["hourly_rate"].strip()))))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect punches: (site, pid) -> [emp, dir, epoch]
    punches = {}
    ever = set()
    for site, (zname, fmt) in sites.items():
        d = os.path.join(inp, "exports", site)
        if not os.path.isdir(d):
            continue
        parser = PARSERS[fmt]
        for path in list_files(d):
            for pid, emp, dr, ep in parser(read_text(path), zname):
                key = (site, pid)
                ever.add(key)
                if key not in punches:
                    punches[key] = [emp, dr, ep]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, "corrections")
    if os.path.isdir(cdir):
        for path in list_files(cdir):
            for r in csv.DictReader(lines_of(read_text(path))):
                r = {(k or "").strip(): (v or "").strip() for k, v in r.items()}
                if not r.get("correction_id"):
                    continue
                try:
                    issued = parse_iso(r["issued_at"])
                except ValueError:
                    continue
                corr.append((issued, r["correction_id"], r))
    corr.sort(key=lambda x: (x[0], x[1]))
    applied = 0
    for issued, cid, r in corr:
        if issued > cutoff:
            continue
        key = (r["site"], r["punch_id"])
        act = r["action"].lower()
        if act == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif act == "set":
            if key in punches:
                try:
                    punches[key][2] = to_epoch(parse_iso(r["time"]))
                except ValueError:
                    continue
                applied += 1
        elif act == "add":
            if key not in ever:
                dr = norm_dir(r["type"])
                try:
                    ep = to_epoch(parse_iso(r["time"]))
                except ValueError:
                    continue
                if dr is None:
                    continue
                punches[key] = [r["employee"], dr, ep]
                ever.add(key)
                applied += 1

    per_emp = {}
    for (site, pid), (emp, dr, ep) in punches.items():
        if emp not in employees:
            continue
        per_emp.setdefault(emp, []).append((ep, 0 if dr == "OUT" else 1, site, pid, dr))

    home_zone = {e: sites[h][0] for e, h in employees.items()}

    stats = {e: dict(shifts=0, paid=0, ot=0, night=0, pay=Fraction(0)) for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0)

    def rnd(ep, site):
        off = exact_offset(ep, sites[site][0])
        rem = (ep + off) % 360
        return ep + (360 - rem if rem >= 180 else -rem)

    for emp, plist in per_emp.items():
        plist.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        hz = home_zone[emp]

        def wd(r):
            return local_date(r, hz)

        kept = []
        last = None
        for ep, _, site, pid, dr in plist:
            r = rnd(ep, site)
            if last is not None and last[1] == dr and ep - last[0] <= 300:
                if pstart <= wd(r) <= pend:
                    exc["duplicates_dropped"] += 1
                continue
            last = (ep, dr)
            kept.append((r, dr, site))

        shifts = []
        pending = None
        for r, dr, site in kept:
            if dr == "IN":
                if pending is not None and pstart <= wd(pending[0]) <= pend:
                    exc["open_shifts"] += 1
                pending = (r, site)
            else:
                if pending is None:
                    if pstart <= wd(r) <= pend:
                        exc["orphan_outs"] += 1
                elif r - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], r, pending[1]))
                    pending = None
                else:
                    if pstart <= wd(pending[0]) <= pend:
                        exc["open_shifts"] += 1
                    if pstart <= wd(r) <= pend:
                        exc["orphan_outs"] += 1
                    pending = None
        if pending is not None and pstart <= wd(pending[0]) <= pend:
            exc["open_shifts"] += 1

        mine = []
        for rin, rout, site in shifts:
            w = wd(rin)
            if not (pstart <= w <= pend):
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(rin, rout, sites[site][0]) // 60, paid)
            mine.append((rin, w, paid, night))
        mine.sort(key=lambda x: x[0])
        day_cum = {}
        week_cum = {}
        st = stats[emp]
        for rin, w, paid, night in mine:
            c = day_cum.get(w, 0)
            dot = max(0, c + paid - 480) - max(0, c - 480)
            day_cum[w] = c + paid
            monday = w - timedelta(days=w.weekday())
            nd = paid - dot
            wc = week_cum.get(monday, 0)
            wot = max(0, wc + nd - 2400) - max(0, wc - 2400)
            week_cum[monday] = wc + nd
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for eff, rv in rates.get(emp, []):
                if eff <= w:
                    rate = rv
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            st["shifts"] += 1
            st["paid"] += paid
            st["ot"] += ot
            st["night"] += night
            st["pay"] += pay

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tot_cents = 0
    for e in employees:
        s = stats[e]
        cents = to_cents(s["pay"])
        out_emps[e] = {
            "shifts": s["shifts"], "paid_minutes": s["paid"], "overtime_minutes": s["ot"],
            "night_minutes": s["night"], "gross": fmt_cents(cents),
        }
        tot["shifts"] += s["shifts"]
        tot["paid_minutes"] += s["paid"]
        tot["overtime_minutes"] += s["ot"]
        tot["night_minutes"] += s["night"]
        tot_cents += cents
    tot["gross"] = fmt_cents(tot_cents)

    result = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": {
            "open_shifts": exc["open_shifts"], "orphan_outs": exc["orphan_outs"],
            "duplicates_dropped": exc["duplicates_dropped"], "corrections_applied": applied,
        },
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outp))
    os.makedirs(d, exist_ok=True)
    with open(outp, "w") as f:
        json.dump(result, f, indent=1, sort_keys=True)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
